`timescale 1ns/1ps
module seven_seg_decoder #( parameter logic ACTIVE_LOW = 1’b1 // set 1 for common-anode (active low segments) ) ( input logic [3:0] nibble, output logic [6:0] seg // {a,b,c,d,e,f,g} ); logic [6:0] seg_raw;
